        "ipa": "/wˈiɹ ɪmpˈaʊɚɪŋ jˈʌŋ θˈɪŋkɚz tˈu ʃˈɛɹ ðˈɛɹ aɪdˈiəz wˈɪð klˈɛɹəti pˈɝpəs ənd ˌɪmpˈækt/",
        "translation": "Chúng tôi trao quyền cho những nhà tư tưởng trẻ để chia sẻ ý tưởng của họ một cách rõ ràng, có mục đích và có sức ảnh hưởng.",
        "start": 68.71499999999999,
