        "ipa": "/ˈɪts nˈoʊ wˈʌndɚ ðˈæt axolotls ˈɑɹ wˈʌn ˈʌv sˈaɪənsəz mˈoʊst stˈʌdid ˈænəməlz/",
        "translation": "Không có gì ngạc nhiên khi kỳ giông axolotl là một trong những loài động vật được khoa học nghiên cứu nhiều nhất,",
